<?php
$uid = (int)$u['id'];
handle('req_create', function () use ($uid) { Pay::request($uid, (string)$_POST['to'], (string)$_POST['amount'], 'BDT', (string)($_POST['note'] ?? '')); return 'Request sent.'; });
handle('req_pay', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $r = Pay::payRequest($uid, (int)$_POST['id'], idem_key()); return $r['status'] === 'approval_pending' ? 'Payment needs approval before it is sent.' : 'Request paid.'; });
handle('req_decline', fn() => Pay::closeRequest($uid, (int)$_POST['id'], 'declined') ?: 'Request declined.');
handle('req_cancel', fn() => Pay::closeRequest($uid, (int)$_POST['id'], 'cancelled') ?: 'Request cancelled.');
echo page_head('Requests', 'Ask for money or pay requests sent to you.');
$in = rows("SELECT r.*, u.name FROM payment_requests r JOIN users u ON u.id=r.requester_id WHERE r.payer_id=? ORDER BY r.id DESC LIMIT 30", [$uid]); $rows = [];
foreach ($in as $r) $rows[] = [e(fdate($r['created_at'], false)), e($r['name']) . '<div class="hint">' . e($r['note']) . '</div>', mny($r['amount'], $r['currency']), badge($r['status']), $r['status'] === 'pending' ? form_start('req_pay', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$r['id'] . '"><div class="row"><input name="pin" type="password" inputmode="numeric" placeholder="PIN" maxlength="6" required aria-label="PIN" style="min-width:90px">' . btn('Pay', 'sm') . '</div></form>' . form_start('req_decline', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$r['id'] . '">' . btn('Decline', 'secondary sm') . '</form>' : ''];
$out = rows("SELECT r.*, u.name FROM payment_requests r JOIN users u ON u.id=r.payer_id WHERE r.requester_id=? ORDER BY r.id DESC LIMIT 30", [$uid]); $rows2 = [];
foreach ($out as $r) $rows2[] = [e(fdate($r['created_at'], false)), e($r['name']) . '<div class="hint">' . e($r['note']) . '</div>', mny($r['amount'], $r['currency']), badge($r['status']), $r['status'] === 'pending' ? form_start('req_cancel', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$r['id'] . '">' . btn('Cancel', 'secondary sm') . '</form>' : ''];
echo '<div class="grid g-main"><div class="grid">' . card('Requests to pay', tbl(['Date', 'From', ['Amount', 'num'], 'Status', ''], $rows, 'No one has asked you for money.')) . card('Requests you sent', tbl(['Date', 'To', ['Amount', 'num'], 'Status', ''], $rows2, 'You have not requested money yet.')) . '</div>' .
  card('Request money', form_start('req_create') . field('Recipient', 'to', 'text', '', 'required placeholder="email or phone"') . field('Amount', 'amount', 'text', '', 'required inputmode="decimal"') . field('Note', 'note', 'text', '', 'maxlength="255"') . btn('Request money') . '</form><p class="hint">The payer sees your name, the amount and your note, and chooses whether to pay. Fees are shown to them before they pay.</p>') . '</div>';
